/* BattleQuiz - Animals & Nature.
 * Each entry carries both languages; `c` is the index of the correct option
 * in BOTH arrays, and `d` is the difficulty level 1-8.
 */
window.BANK = window.BANK || [];
window.BANK.push(
  { id:"nat001", t:"nature", d:1, c:0, en:{q:"Which animal says \"moo\"?",a:["Cow","Dog","Cat","Duck"]}, tr:{q:"Hangi hayvan \"mö\" diye ses çıkarır?",a:["İnek","Köpek","Kedi","Ördek"]}, ex:{en:"Cows make a low, drawn-out \"moo\" sound to call to each other across a field.",tr:"İnekler, tarlada birbirlerini çağırmak için uzun ve alçak sesli bir \"mö\" sesi çıkarır."} },
  { id:"nat002", t:"nature", d:1, c:0, en:{q:"How many legs does a spider have?",a:["Eight","Six","Four","Ten"]}, tr:{q:"Bir örümceğin kaç bacağı vardır?",a:["Sekiz","Altı","Dört","On"]}, ex:{en:"Spiders have eight legs, which is one way to tell them apart from six-legged insects.",tr:"Örümceklerin sekiz bacağı vardır; bu, onları altı bacaklı böceklerden ayıran bir özelliktir."} },
  { id:"nat003", t:"nature", d:1, c:0, en:{q:"What is a baby chicken called?",a:["Chick","Lamb","Calf","Foal"]}, tr:{q:"Tavuğun yavrusuna ne ad verilir?",a:["Civciv","Kuzu","Buzağı","Tay"]}, ex:{en:"A young chicken, before it grows feathers and gets bigger, is called a chick.",tr:"Tüyleri çıkıp büyümeden önceki genç tavuğa civciv denir."} },
  { id:"nat004", t:"nature", d:1, c:0, en:{q:"Where do fish live?",a:["In water","In trees","Under the ground","In the clouds"]}, tr:{q:"Balıklar nerede yaşar?",a:["Suda","Ağaçlarda","Toprak altında","Bulutlarda"]}, ex:{en:"Fish have gills instead of lungs, so they take oxygen straight from the water they live in.",tr:"Balıkların akciğer yerine solungacı vardır, bu yüzden yaşadıkları sudan doğrudan oksijen alırlar."} },
  { id:"nat005", t:"nature", d:1, c:0, en:{q:"Where does rain come from?",a:["Clouds","Trees","Rocks","Mountains"]}, tr:{q:"Yağmur nereden gelir?",a:["Bulutlar","Ağaçlar","Kayalar","Dağlar"]}, ex:{en:"Water vapour rises, cools and gathers into clouds, then falls back down as rain.",tr:"Su buharı yükselir, soğur ve bulutlarda birikir, sonra yağmur olarak tekrar yere düşer."} },
  { id:"nat006", t:"nature", d:1, c:0, en:{q:"Which season is the coldest?",a:["Winter","Summer","Spring","Autumn"]}, tr:{q:"En soğuk mevsim hangisidir?",a:["Kış","Yaz","İlkbahar","Sonbahar"]}, ex:{en:"Winter is coldest because that hemisphere is tilted furthest away from the Sun.",tr:"Kış en soğuk mevsimdir çünkü o yarımküre Güneş'ten en uzağa eğik konumdadır."} },
  { id:"nat007", t:"nature", d:1, c:0, en:{q:"Which part of a plant is under the ground?",a:["The roots","The flower","The leaves","The fruit"]}, tr:{q:"Bitkinin hangi bölümü toprağın altındadır?",a:["Kökler","Çiçek","Yapraklar","Meyve"]}, ex:{en:"Roots grow underground, anchoring the plant and drawing up water and nutrients.",tr:"Kökler toprağın altında büyür, bitkiyi sabitler ve su ile besin maddelerini çeker."} },
  { id:"nat008", t:"nature", d:1, c:0, en:{q:"What colour is grass usually?",a:["Green","Blue","Red","Purple"]}, tr:{q:"Çimenler genellikle ne renktir?",a:["Yeşil","Mavi","Kırmızı","Mor"]}, ex:{en:"Grass looks green because it is full of chlorophyll, the substance plants use to catch sunlight.",tr:"Çim yeşil görünür çünkü bitkilerin güneş ışığını yakalamak için kullandığı klorofille doludur."} },
  { id:"nat009", t:"nature", d:1, c:0, en:{q:"Which animal gives us wool?",a:["Sheep","Chicken","Fish","Horse"]}, tr:{q:"Yün hangi hayvandan elde edilir?",a:["Koyun","Tavuk","Balık","At"]}, ex:{en:"Sheep grow a thick, curly coat of wool that farmers shear off once it grows long.",tr:"Koyunlar kalın ve kıvırcık bir yün tabakası büyütür, çiftçiler uzayınca bunu kırkar."} },
  { id:"nat010", t:"nature", d:1, c:0, en:{q:"What do birds build in trees to live in?",a:["A nest","A spider web","A tunnel","A shell"]}, tr:{q:"Kuşlar ağaçlarda yaşamak için ne yapar?",a:["Yuva","Örümcek ağı","Tünel","Kabuk"]}, ex:{en:"Birds weave twigs and grass into a nest to keep their eggs and chicks safe.",tr:"Kuşlar, yumurtalarını ve yavrularını güvende tutmak için dal ve otlardan yuva örer."} },
  { id:"nat011", t:"nature", d:1, c:0, en:{q:"Which animal has black and white stripes?",a:["Zebra","Elephant","Frog","Pig"]}, tr:{q:"Hangi hayvanın siyah beyaz çizgileri vardır?",a:["Zebra","Fil","Kurbağa","Domuz"]}, ex:{en:"Every zebra's black and white stripe pattern is unique, like a human fingerprint.",tr:"Her zebranın siyah beyaz çizgi deseni, insan parmak izi gibi kendine özgüdür."} },
  { id:"nat012", t:"nature", d:1, c:0, en:{q:"Which animal carries its baby in a pouch on its tummy?",a:["Kangaroo","Horse","Chicken","Turtle"]}, tr:{q:"Hangi hayvan yavrusunu karnındaki kesede taşır?",a:["Kanguru","At","Tavuk","Kaplumbağa"]}, ex:{en:"A kangaroo carries its tiny, underdeveloped baby in a pouch until it is strong enough to hop out.",tr:"Kanguru, minik ve az gelişmiş yavrusunu dışarı zıplayacak kadar güçlenene dek kesesinde taşır."} },
  { id:"nat013", t:"nature", d:1, c:0, en:{q:"Which of these do rabbits like to eat?",a:["Carrots","Meat","Fish","Cheese"]}, tr:{q:"Tavşanlar bunlardan hangisini yemeyi sever?",a:["Havuç","Et","Balık","Peynir"]}, ex:{en:"Rabbits enjoy crunchy vegetables like carrots, though hay makes up most of their real diet.",tr:"Tavşanlar havuç gibi çıtır sebzeleri sever, ama asıl beslenmelerinin çoğunu ot oluşturur."} },
  { id:"nat014", t:"nature", d:1, k:"tf", v:true, en:{q:"Snails carry their shells on their backs."}, tr:{q:"Salyangozlar kabuklarını sırtlarında taşır."}, ex:{en:"A snail's shell grows attached to its body and it carries that shell everywhere it goes.",tr:"Salyangozun kabuğu vücuduna bağlı olarak büyür ve onu gittiği her yere taşır."} },
  { id:"nat015", t:"nature", d:1, k:"tf", v:false, en:{q:"Ladybirds are green with black spots."}, tr:{q:"Uğur böcekleri siyah benekli ve yeşil renklidir."}, ex:{en:"Ladybirds are usually red or orange with black spots, not green.",tr:"Uğur böcekleri genellikle siyah benekli kırmızı veya turuncu renktedir, yeşil değil."} },
  { id:"nat016", t:"nature", d:1, k:"tf", v:true, en:{q:"A rainbow can appear in the sky after it rains."}, tr:{q:"Yağmur yağdıktan sonra gökyüzünde gökkuşağı görülebilir."}, ex:{en:"Rainbows form when sunlight passes through raindrops still hanging in the air, so they often follow rain.",tr:"Gökkuşağı, güneş ışığı havada asılı kalan yağmur damlalarından geçtiğinde oluşur, bu yüzden çoğu zaman yağmurdan sonra görülür."} },
  { id:"nat017", t:"nature", d:1, k:"tf", v:false, en:{q:"Potatoes grow on trees."}, tr:{q:"Patatesler ağaçlarda yetişir."}, ex:{en:"Potatoes grow underground on the roots of a low plant; they are not a fruit from a tree.",tr:"Patates, alçak bir bitkinin köklerinde toprağın altında yetişir; bir ağacın meyvesi değildir."} },
  { id:"nat018", t:"nature", d:1, k:"tf", v:true, en:{q:"Birds' bodies are covered with feathers."}, tr:{q:"Kuşların vücudu tüylerle kaplıdır."}, ex:{en:"Feathers cover a bird's body, keeping it warm and helping it fly.",tr:"Tüyler kuşun vücudunu kaplar, onu sıcak tutar ve uçmasına yardımcı olur."} },
  { id:"nat019", t:"nature", d:1, k:"tf", v:false, en:{q:"Spring comes right after summer."}, tr:{q:"İlkbahar, yazdan hemen sonra gelir."}, ex:{en:"The seasons run winter, spring, summer, then autumn, so spring comes before summer, not after.",tr:"Mevsimler kış, ilkbahar, yaz, sonra sonbahar sırasıyla gelir; yani ilkbahar yazdan önce gelir, sonra değil."} },
  { id:"nat020", t:"nature", d:2, c:0, en:{q:"Which animal is famous for its very long neck?",a:["Giraffe","Camel","Horse","Deer"]}, tr:{q:"Hangi hayvan çok uzun boynuyla ünlüdür?",a:["Zürafa","Deve","At","Geyik"]}, ex:{en:"A giraffe's neck can be about two metres long, helping it reach leaves high in trees.",tr:"Zürafanın boynu yaklaşık iki metre uzunluğunda olabilir, bu da ağaçlardaki yüksek yaprakları yemesine yardımcı olur."} },
  { id:"nat021", t:"nature", d:2, c:0, en:{q:"What do bees make in their hive?",a:["Honey","Milk","Silk","Butter"]}, tr:{q:"Arılar kovanlarında ne üretir?",a:["Bal","Süt","İpek","Tereyağı"]}, ex:{en:"Worker bees collect nectar from flowers and turn it into honey to feed the hive.",tr:"İşçi arılar çiçeklerden nektar toplar ve kovanı beslemek için bunu bala dönüştürür."} },
  { id:"nat022", t:"nature", d:2, c:0, en:{q:"What is a baby horse called?",a:["Foal","Lamb","Calf","Chick"]}, tr:{q:"Atın yavrusuna ne ad verilir?",a:["Tay","Kuzu","Buzağı","Civciv"]}, ex:{en:"A young horse, before it grows into an adult, is called a foal.",tr:"Yetişkin bir at olmadan önceki genç ata tay denir."} },
  { id:"nat023", t:"nature", d:2, c:0, en:{q:"What is the loud rumbling sound heard after lightning called?",a:["Thunder","Rainbow","Fog","Wind"]}, tr:{q:"Şimşekten sonra duyulan gürültülü sese ne denir?",a:["Gök gürültüsü","Gökkuşağı","Sis","Rüzgâr"]}, ex:{en:"Thunder is the sound made by air rapidly expanding along a lightning bolt's path.",tr:"Gök gürültüsü, şimşeğin izlediği yol boyunca havanın aniden genişlemesiyle oluşan sestir."} },
  { id:"nat024", t:"nature", d:2, c:0, en:{q:"Which insect glows in the dark at night?",a:["Firefly","Ladybird","Ant","Grasshopper"]}, tr:{q:"Hangi böcek geceleri karanlıkta ışık saçar?",a:["Ateş böceği","Uğur böceği","Karınca","Çekirge"]}, ex:{en:"Fireflies glow through a chemical reaction inside their bodies, flashing to attract mates.",tr:"Ateş böcekleri vücutlarındaki kimyasal bir tepkimeyle parlar ve eş çekmek için yanıp söner."} },
  { id:"nat025", t:"nature", d:2, c:0, en:{q:"An acorn grows into which kind of tree?",a:["Oak","Pine","Willow","Poplar"]}, tr:{q:"Palamut büyüyünce hangi ağaç olur?",a:["Meşe","Çam","Söğüt","Kavak"]}, ex:{en:"An acorn is the seed of an oak tree, and given time it can grow into a new oak.",tr:"Meşe palamudu, bir meşe ağacının tohumudur ve zamanla yeni bir meşe ağacına dönüşebilir."} },
  { id:"nat026", t:"nature", d:2, c:0, en:{q:"In which season do many trees' leaves turn yellow and fall?",a:["Autumn","Spring","Summer","Winter"]}, tr:{q:"Birçok ağacın yaprakları hangi mevsimde sararıp dökülür?",a:["Sonbahar","İlkbahar","Yaz","Kış"]}, ex:{en:"In autumn, trees stop making green chlorophyll, revealing yellow and orange colours before leaves fall.",tr:"Sonbaharda ağaçlar yeşil klorofil üretmeyi bırakır, yapraklar dökülmeden önce sarı ve turuncu renkler ortaya çıkar."} },
  { id:"nat027", t:"nature", d:2, c:0, en:{q:"Which bird cannot fly but swims very well?",a:["Penguin","Eagle","Parrot","Sparrow"]}, tr:{q:"Hangi kuş uçamaz ama çok iyi yüzer?",a:["Penguen","Kartal","Papağan","Serçe"]}, ex:{en:"Penguins have wings shaped like flippers built for swimming, not flying through air.",tr:"Penguenlerin kanatları uçmak için değil, yüzmek için paletlere benzer şekildedir."} },
  { id:"nat028", t:"nature", d:2, c:0, en:{q:"Which animal has a hump on its back?",a:["Camel","Horse","Cow","Donkey"]}, tr:{q:"Hangi hayvanın sırtında hörgüç bulunur?",a:["Deve","At","İnek","Eşek"]}, ex:{en:"A camel's hump stores fat, which its body can use for energy and water when food is scarce.",tr:"Devenin hörgücü yağ depolar; besin azaldığında vücudu bunu enerji ve su için kullanabilir."} },
  { id:"nat029", t:"nature", d:2, c:0, en:{q:"Which animal builds dams across streams?",a:["Beaver","Otter","Duck","Frog"]}, tr:{q:"Hangi hayvan dereleri kapatarak baraj yapar?",a:["Kunduz","Su samuru","Ördek","Kurbağa"]}, ex:{en:"Beavers gnaw down trees and pile the branches into dams to create still ponds for their lodges.",tr:"Kunduzlar ağaçları kemirip dallarını yığarak barınakları için durgun göletler oluşturan setler yapar."} },
  { id:"nat030", t:"nature", d:2, c:0, en:{q:"What do giant pandas mostly eat?",a:["Bamboo","Bananas","Fish","Nuts"]}, tr:{q:"Dev pandalar ağırlıklı olarak neyle beslenir?",a:["Bambu","Muz","Balık","Fındık"]}, ex:{en:"Giant pandas spend most of their day eating bamboo, which makes up nearly all of their diet.",tr:"Dev pandalar günlerinin büyük kısmını bambu yiyerek geçirir; bu, beslenmelerinin neredeyse tamamını oluşturur."} },
  { id:"nat031", t:"nature", d:2, c:0, en:{q:"Which bird usually hunts at night?",a:["Owl","Sparrow","Chicken","Pigeon"]}, tr:{q:"Hangi kuş genellikle geceleri avlanır?",a:["Baykuş","Serçe","Tavuk","Güvercin"]}, ex:{en:"Owls have huge eyes and sharp hearing that let them hunt small animals after dark.",tr:"Baykuşların iri gözleri ve keskin işitme duyusu, karanlıkta küçük hayvanları avlamalarını sağlar."} },
  { id:"nat032", t:"nature", d:2, k:"tf", v:false, en:{q:"Bats are blind."}, tr:{q:"Yarasalar kördür."}, ex:{en:"Bats can see, though many also use echolocation, bouncing sound off objects to find their way in the dark.",tr:"Yarasalar görebilir; ayrıca birçoğu karanlıkta yol bulmak için sesi cisimlere çarptırıp yankısını dinleyen ekolokasyonu kullanır."} },
  { id:"nat033", t:"nature", d:2, k:"tf", v:true, en:{q:"Frogs begin their lives as tadpoles that live in water."}, tr:{q:"Kurbağalar hayata suda yaşayan iribaşlar olarak başlar."}, ex:{en:"Frog eggs hatch into tadpoles, which live and breathe in water before growing legs and lungs.",tr:"Kurbağa yumurtaları, bacak ve akciğer geliştirmeden önce suda yaşayıp nefes alan iribaşlara dönüşür."} },
  { id:"nat034", t:"nature", d:2, k:"tf", v:true, en:{q:"Dolphins have to come up to the surface to breathe air."}, tr:{q:"Yunuslar nefes almak için su yüzeyine çıkmak zorundadır."}, ex:{en:"Dolphins are mammals, not fish, so they must surface regularly to breathe air through a blowhole.",tr:"Yunuslar balık değil memelidir, bu yüzden düzenli olarak yüzeye çıkıp deliklerinden hava solumak zorundadırlar."} },
  { id:"nat035", t:"nature", d:2, k:"tf", v:false, en:{q:"A rainbow is made up of five colours."}, tr:{q:"Gökkuşağı beş renkten oluşur."}, ex:{en:"A rainbow shows seven colours: red, orange, yellow, green, blue, indigo and violet.",tr:"Gökkuşağı kırmızı, turuncu, sarı, yeşil, mavi, lacivert ve mor olmak üzere yedi renk gösterir."} },
  { id:"nat036", t:"nature", d:2, k:"tf", v:true, en:{q:"A cactus stores water inside its thick stem."}, tr:{q:"Kaktüs, kalın gövdesinin içinde su depolar."}, ex:{en:"A cactus has a thick, spongy stem that soaks up and holds water for long dry spells.",tr:"Kaktüsün kalın ve süngerimsi bir gövdesi vardır; bu, uzun kurak dönemler için suyu emip depolar."} },
  { id:"nat037", t:"nature", d:2, k:"tf", v:false, en:{q:"Penguins live in the wild at the North Pole."}, tr:{q:"Penguenler doğada Kuzey Kutbu'nda yaşar."}, ex:{en:"Almost all wild penguins live in the Southern Hemisphere, not near the North Pole.",tr:"Yaban penguenlerin neredeyse tamamı Kuzey Kutbu yakınında değil, Güney Yarımküre'de yaşar."} },
  { id:"nat038", t:"nature", d:3, c:0, en:{q:"Which of these animals is a mammal?",a:["Dolphin","Shark","Crocodile","Eagle"]}, tr:{q:"Bu hayvanlardan hangisi memelidir?",a:["Yunus","Köpekbalığı","Timsah","Kartal"]}, ex:{en:"A dolphin is a mammal: it is warm-blooded, breathes air, and feeds its young milk, unlike a fish.",tr:"Yunus bir memelidir: sıcakkanlıdır, hava soluyup akciğer kullanır ve yavrusunu sütle besler, balıklardan farklı olarak."} },
  { id:"nat039", t:"nature", d:3, c:0, en:{q:"Which stage does a caterpillar pass through before becoming a butterfly?",a:["Pupa","Egg","Larva","Nymph"]}, tr:{q:"Tırtıl kelebeğe dönüşmeden önce hangi evreden geçer?",a:["Pupa (koza)","Yumurta","Larva","Nimf"]}, ex:{en:"Inside the pupa, or chrysalis, the caterpillar's body is completely rebuilt into a butterfly.",tr:"Pupa, yani koza içinde tırtılın vücudu tamamen yeniden yapılanarak kelebeğe dönüşür."} },
  { id:"nat040", t:"nature", d:3, c:0, en:{q:"Which is the largest animal living on land?",a:["African elephant","Giraffe","Rhinoceros","Hippopotamus"]}, tr:{q:"Karada yaşayan en büyük hayvan hangisidir?",a:["Afrika fili","Zürafa","Gergedan","Su aygırı"]}, ex:{en:"The African elephant can weigh over six tonnes, making it the heaviest animal on land.",tr:"Afrika fili altı tonun üzerinde ağırlığa ulaşabilir, bu da onu karadaki en ağır hayvan yapar."} },
  { id:"nat041", t:"nature", d:3, c:0, en:{q:"Which gas do plants take in from the air to make their food?",a:["Carbon dioxide","Oxygen","Nitrogen","Helium"]}, tr:{q:"Bitkiler besinlerini üretmek için havadan hangi gazı alır?",a:["Karbondioksit","Oksijen","Azot","Helyum"]}, ex:{en:"Plants pull carbon dioxide from the air and combine it with water and light to make food.",tr:"Bitkiler havadan karbondioksit çeker ve besin üretmek için bunu suyla ve ışıkla birleştirir."} },
  { id:"nat042", t:"nature", d:3, c:0, en:{q:"What do you count on a cut tree trunk to work out the tree's age?",a:["The rings","The leaves","The branches","The roots"]}, tr:{q:"Kesilmiş bir ağaç gövdesinde ağacın yaşını bulmak için ne sayılır?",a:["Halkalar","Yapraklar","Dallar","Kökler"]}, ex:{en:"A tree grows one new ring each year, so counting them tells you roughly how old it is.",tr:"Bir ağaç her yıl bir yeni halka oluşturur, bu yüzden halkaları saymak yaşını gösterir."} },
  { id:"nat043", t:"nature", d:3, c:0, en:{q:"What does a camel store inside its hump?",a:["Fat","Water","Air","Sand"]}, tr:{q:"Deve, hörgücünün içinde ne depolar?",a:["Yağ","Su","Hava","Kum"]}, ex:{en:"A camel's hump is mostly fat, which its body breaks down for energy and water when needed.",tr:"Devenin hörgücü büyük ölçüde yağdan oluşur; vücudu ihtiyaç halinde bunu enerji ve suya çevirir."} },
  { id:"nat044", t:"nature", d:3, c:0, en:{q:"Which of these birds cannot fly?",a:["Ostrich","Eagle","Seagull","Owl"]}, tr:{q:"Bu kuşlardan hangisi uçamaz?",a:["Deve kuşu","Kartal","Martı","Baykuş"]}, ex:{en:"The ostrich is the world's largest bird, too heavy to fly, but it can run extremely fast instead.",tr:"Devekuşu dünyanın en büyük kuşudur, uçamayacak kadar ağırdır ama bunun yerine çok hızlı koşabilir."} },
  { id:"nat045", t:"nature", d:3, c:0, en:{q:"What do we call an animal that eats only plants?",a:["A herbivore","A carnivore","An omnivore","A predator"]}, tr:{q:"Sadece bitkilerle beslenen hayvanlara ne ad verilir?",a:["Otçul","Etçil","Hepçil","Yırtıcı"]}, ex:{en:"A herbivore is an animal whose diet is entirely plants, like leaves, grass or fruit.",tr:"Otobur, beslenmesi tamamen yaprak, ot ya da meyve gibi bitkilerden oluşan hayvandır."} },
  { id:"nat046", t:"nature", d:3, c:0, en:{q:"Which of these habitats gets the least rain?",a:["Desert","Rainforest","Swamp","Grassland"]}, tr:{q:"Bu yaşam alanlarından hangisine en az yağmur yağar?",a:["Çöl","Yağmur ormanı","Bataklık","Çayır"]}, ex:{en:"Deserts receive very little rainfall each year, which is what defines them as deserts.",tr:"Çöller her yıl çok az yağış alır; onları çöl yapan da tam olarak budur."} },
  { id:"nat047", t:"nature", d:3, c:0, en:{q:"What do we call frozen rain that falls as small balls of ice?",a:["Hail","Frost","Dew","Fog"]}, tr:{q:"Küçük buz topları hâlinde düşen donmuş yağışa ne denir?",a:["Dolu","Kırağı","Çiy","Sis"]}, ex:{en:"Hail forms when strong winds inside a storm carry raindrops up and down until they freeze into balls of ice.",tr:"Dolu, bir fırtınadaki güçlü rüzgârların yağmur damlalarını yukarı aşağı taşıyarak buz topları hâline dondurmasıyla oluşur."} },
  { id:"nat048", t:"nature", d:3, c:0, en:{q:"What do we call the colours and patterns that help an animal blend into its surroundings?",a:["Camouflage","Migration","Pollination","Metamorphosis"]}, tr:{q:"Bir hayvanın çevresine karışmasını sağlayan renk ve desenlere ne ad verilir?",a:["Kamuflaj","Göç","Tozlaşma","Başkalaşım"]}, ex:{en:"Camouflage lets an animal's colours and patterns match its surroundings, hiding it from predators or prey.",tr:"Kamuflaj, bir hayvanın renk ve deseninin çevresine uyarak onu avcılardan ya da avından gizlemesini sağlar."} },
  { id:"nat049", t:"nature", d:3, c:0, en:{q:"Which of these fabrics is made from the cocoon of an insect?",a:["Silk","Wool","Cotton","Linen"]}, tr:{q:"Bu kumaşlardan hangisi bir böceğin kozasından elde edilir?",a:["İpek","Yün","Pamuk","Keten"]}, ex:{en:"Silk fibre is unwound from the cocoon spun by a silkworm, the caterpillar of a moth.",tr:"İpek lifi, bir güve tırtılı olan ipekböceğinin ördüğü kozadan çözülerek elde edilir."} },
  { id:"nat050", t:"nature", d:3, c:0, en:{q:"Which small creature digs tunnels in soil and helps plants grow?",a:["Earthworm","Butterfly","Grasshopper","Ladybird"]}, tr:{q:"Hangi küçük canlı toprakta tüneller açarak bitkilerin büyümesine yardım eder?",a:["Solucan","Kelebek","Çekirge","Uğur böceği"]}, ex:{en:"Earthworms tunnel through soil, letting air and water reach plant roots more easily.",tr:"Solucanlar toprakta tüneller açarak havanın ve suyun bitki köklerine daha kolay ulaşmasını sağlar."} },
  { id:"nat051", t:"nature", d:3, c:0, en:{q:"Which of these animals died out long ago and no longer exists?",a:["The dodo","The panda","The tiger","The zebra"]}, tr:{q:"Bu hayvanlardan hangisi çok uzun zaman önce yok oldu ve artık yaşamıyor?",a:["Dodo kuşu","Panda","Kaplan","Zebra"]}, ex:{en:"The dodo, a flightless bird from Mauritius, went extinct in the late 1600s after humans arrived.",tr:"Uçamayan bir kuş olan dodo, Mauritius'ta insanların gelişinden sonra 1600'lerin sonunda tamamen yok oldu."} },
  { id:"nat052", t:"nature", d:3, k:"tf", v:false, en:{q:"Mushrooms are plants that make their own food using sunlight."}, tr:{q:"Mantarlar, güneş ışığını kullanarak kendi besinini üreten bitkilerdir."}, ex:{en:"Mushrooms are fungi, not plants; they cannot make their own food from sunlight and instead absorb it from around them.",tr:"Mantarlar bitki değil, funguslardır; güneş ışığından kendi besinlerini üretemez, çevrelerinden emerler."} },
  { id:"nat053", t:"nature", d:3, k:"tf", v:true, en:{q:"In a storm we see the lightning before we hear the thunder, because light travels faster than sound."}, tr:{q:"Fırtınada şimşeği gök gürültüsünden önce görürüz, çünkü ışık sesten daha hızlı yol alır."}, ex:{en:"Light reaches your eyes almost instantly, while sound travels far slower, so thunder always lags behind the flash.",tr:"Işık gözlerine neredeyse anında ulaşır, ses ise çok daha yavaş yayılır, bu yüzden gök gürültüsü şimşekten hep geriden gelir."} },
  { id:"nat054", t:"nature", d:3, k:"tf", v:false, en:{q:"African elephants have smaller ears than Asian elephants."}, tr:{q:"Afrika fillerinin kulakları, Asya fillerininkinden daha küçüktür."}, ex:{en:"African elephants actually have larger ears than Asian elephants, which help them lose body heat.",tr:"Afrika fillerinin kulakları aslında Asya fillerinden daha büyüktür ve vücut ısısını atmalarına yardımcı olur."} },
  { id:"nat055", t:"nature", d:3, k:"tf", v:true, en:{q:"Ladybirds feed on aphids, the tiny insects that damage garden plants."}, tr:{q:"Uğur böcekleri, bahçe bitkilerine zarar veren küçük yaprak bitleriyle beslenir."}, ex:{en:"Ladybirds are useful in gardens because they hunt and eat aphids, tiny pests that harm plants.",tr:"Uğur böcekleri bahçelerde faydalıdır çünkü bitkilere zarar veren küçük zararlılar olan yaprak bitlerini avlayıp yer."} },
  { id:"nat056", t:"nature", d:4, c:0, en:{q:"Which is the fastest land animal?",a:["Cheetah","Lion","Horse","Gazelle"]}, tr:{q:"En hızlı kara hayvanı hangisidir?",a:["Çita","Aslan","At","Ceylan"]}, ex:{en:"A cheetah can sprint over 100 km/h in short bursts, making it the fastest animal on land.",tr:"Çita kısa mesafelerde saatte 100 kilometreyi aşan hızlara çıkabilir, bu da onu karadaki en hızlı hayvan yapar."} },
  { id:"nat057", t:"nature", d:4, c:0, en:{q:"Where do polar bears live in the wild?",a:["The Arctic","Antarctica","The Sahara","The Amazon"]}, tr:{q:"Kutup ayıları doğada nerede yaşar?",a:["Kuzey Kutbu","Antarktika","Sahra Çölü","Amazon"]}, ex:{en:"Polar bears live around the Arctic Ocean, hunting seals on the sea ice.",tr:"Kutup ayıları, deniz buzunda fok avlayarak Kuzey Buz Denizi çevresinde yaşar."} },
  { id:"nat058", t:"nature", d:4, c:0, en:{q:"Which of these is a reptile?",a:["Tortoise","Frog","Whale","Penguin"]}, tr:{q:"Bunlardan hangisi sürüngendir?",a:["Kaplumbağa","Kurbağa","Balina","Penguen"]}, ex:{en:"A tortoise is a reptile: cold-blooded, scaly-skinned, and it lays eggs on land.",tr:"Kaplumbağa bir sürüngendir: soğukkanlıdır, pullu derisi vardır ve karada yumurtlar."} },
  { id:"nat059", t:"nature", d:4, c:0, en:{q:"What can you work out by counting the rings inside a tree trunk?",a:["Its age","Its height","Its species","How much water it holds"]}, tr:{q:"Bir ağaç gövdesindeki halkaları sayarak ne öğrenebilirsiniz?",a:["Yaşını","Boyunu","Türünü","İçindeki su miktarını"]}, ex:{en:"Each ring in a tree trunk marks one year of growth, so counting them gives its age.",tr:"Bir ağaç gövdesindeki her halka bir yıllık büyümeyi gösterir, bu yüzden sayılması yaşını verir."} },
  { id:"nat060", t:"nature", d:4, c:0, en:{q:"In a food chain, what are green plants that make their own food called?",a:["Producers","Consumers","Decomposers","Predators"]}, tr:{q:"Besin zincirinde kendi besinini üreten yeşil bitkilere ne ad verilir?",a:["Üreticiler","Tüketiciler","Ayrıştırıcılar","Yırtıcılar"]}, ex:{en:"Producers, like green plants, make their own food from sunlight and sit at the base of every food chain.",tr:"Yeşil bitkiler gibi üreticiler, güneş ışığından kendi besinlerini üretir ve her besin zincirinin temelinde yer alır."} },
  { id:"nat061", t:"nature", d:4, c:0, en:{q:"What is the movement of pollen from one flower to another called?",a:["Pollination","Germination","Photosynthesis","Digestion"]}, tr:{q:"Polenin bir çiçekten başka bir çiçeğe taşınmasına ne denir?",a:["Tozlaşma","Çimlenme","Fotosentez","Sindirim"]}, ex:{en:"Pollination carries pollen from one flower to another, letting plants make seeds.",tr:"Tozlaşma, polenin bir çiçekten diğerine taşınmasıdır ve bitkilerin tohum oluşturmasını sağlar."} },
  { id:"nat062", t:"nature", d:4, c:0, en:{q:"Most bats find their way and hunt in the dark using what?",a:["Sound echoes","Smell","Heat vision","Starlight"]}, tr:{q:"Yarasaların çoğu karanlıkta yolunu nasıl bulur ve avlanır?",a:["Ses yankılarıyla","Koku alarak","Isı görüşüyle","Yıldız ışığıyla"]}, ex:{en:"Bats send out high-pitched sounds and listen to the echoes bouncing back to locate prey in the dark.",tr:"Yarasalar tiz sesler çıkarır ve karanlıkta avlarını bulmak için geri dönen yankıları dinler."} },
  { id:"nat063", t:"nature", d:4, c:0, en:{q:"Which bird is known for laying its eggs in other birds' nests?",a:["Cuckoo","Stork","Woodpecker","Nightingale"]}, tr:{q:"Hangi kuş yumurtalarını başka kuşların yuvasına bırakmasıyla bilinir?",a:["Guguk kuşu","Leylek","Ağaçkakan","Bülbül"]}, ex:{en:"The cuckoo lays its eggs in other birds' nests, tricking them into raising its chicks.",tr:"Guguk kuşu yumurtalarını başka kuşların yuvasına bırakarak onları yavrularını büyütmeye kandırır."} },
  { id:"nat064", t:"nature", d:4, c:0, en:{q:"Which instrument is used to measure wind speed?",a:["Anemometer","Barometer","Thermometer","Hygrometer"]}, tr:{q:"Rüzgâr hızını ölçmek için hangi alet kullanılır?",a:["Anemometre","Barometre","Termometre","Higrometre"]}, ex:{en:"An anemometer has spinning cups that turn faster in stronger wind, showing its speed.",tr:"Anemometrenin dönen kaseleri güçlü rüzgârda daha hızlı döner ve böylece hızını gösterir."} },
  { id:"nat065", t:"nature", d:4, c:0, en:{q:"Corals are which kind of living thing?",a:["Animals","Plants","Fungi","Bacteria"]}, tr:{q:"Mercanlar hangi tür canlılardır?",a:["Hayvanlar","Bitkiler","Mantarlar","Bakteriler"]}, ex:{en:"Corals are tiny animals related to jellyfish that build hard skeletons, forming reefs over time.",tr:"Mercanlar, denizanasıyla akraba küçük hayvanlardır ve zamanla resif oluşturan sert iskeletler inşa ederler."} },
  { id:"nat066", t:"nature", d:4, c:0, en:{q:"Which land habitat holds the greatest variety of plant and animal species?",a:["Tropical rainforest","Tundra","Desert","Temperate grassland"]}, tr:{q:"Hangi kara yaşam alanı en fazla bitki ve hayvan türü çeşitliliğine sahiptir?",a:["Tropikal yağmur ormanı","Tundra","Çöl","Ilıman çayır"]}, ex:{en:"Tropical rainforests are warm and wet all year, conditions that support more species than any other habitat.",tr:"Tropikal yağmur ormanları yıl boyunca sıcak ve nemlidir; bu koşullar başka hiçbir yaşam alanının barındırmadığı kadar tür destekler."} },
  { id:"nat067", t:"nature", d:4, c:0, en:{q:"In the water cycle, what is water vapour turning back into liquid called?",a:["Condensation","Evaporation","Precipitation","Erosion"]}, tr:{q:"Su döngüsünde su buharının yeniden sıvıya dönüşmesine ne ad verilir?",a:["Yoğuşma","Buharlaşma","Yağış","Erozyon"]}, ex:{en:"Condensation happens when rising water vapour cools and turns back into tiny liquid droplets, forming clouds.",tr:"Yoğuşma, yükselen su buharının soğuyup küçük sıvı damlacıklara dönüşerek bulut oluşturmasıdır."} },
  { id:"nat068", t:"nature", d:4, c:0, en:{q:"Which of these trees keeps its leaves through the winter?",a:["Pine","Oak","Beech","Poplar"]}, tr:{q:"Bu ağaçlardan hangisi kış boyunca yapraklarını dökmez?",a:["Çam","Meşe","Kayın","Kavak"]}, ex:{en:"Pine is an evergreen conifer, keeping its needle-like leaves all year instead of shedding them in autumn.",tr:"Çam her dem yeşil bir ibreli ağaçtır; iğne yapraklarını sonbaharda dökmek yerine yıl boyu tutar."} },
  { id:"nat069", t:"nature", d:4, k:"tf", v:true, en:{q:"A shark's skeleton is made of cartilage instead of bone."}, tr:{q:"Köpekbalığının iskeleti kemikten değil kıkırdaktan oluşur."}, ex:{en:"Sharks have skeletons made of flexible cartilage, the same material as the tip of your nose, not bone.",tr:"Köpekbalıklarının iskeleti kemikten değil, burnunun ucuyla aynı esnek maddeden, yani kıkırdaktan oluşur."} },
  { id:"nat070", t:"nature", d:4, k:"tf", v:false, en:{q:"An owl can turn its head a full 360 degrees."}, tr:{q:"Bir baykuş başını tam 360 derece döndürebilir."}, ex:{en:"An owl can turn its head about 270 degrees, an impressive range but not a full circle.",tr:"Bir baykuş başını yaklaşık 270 derece çevirebilir; bu etkileyici bir açıdır ama tam bir tur değildir."} },
  { id:"nat071", t:"nature", d:4, k:"tf", v:true, en:{q:"An adult insect's body has three main parts: head, thorax and abdomen."}, tr:{q:"Yetişkin bir böceğin vücudu baş, göğüs ve karın olmak üzere üç ana bölümden oluşur."}, ex:{en:"An adult insect's body is divided into three parts: the head, thorax and abdomen.",tr:"Yetişkin bir böceğin vücudu baş, göğüs ve karın olmak üzere üç bölümden oluşur."} },
  { id:"nat072", t:"nature", d:4, k:"tf", v:false, en:{q:"Thunder is the sound made when two clouds crash into each other."}, tr:{q:"Gök gürültüsü, iki bulutun birbirine çarpmasıyla oluşan sestir."}, ex:{en:"Thunder is the sound of air rapidly expanding along the path of a lightning bolt, not clouds colliding.",tr:"Gök gürültüsü, bulutların çarpışmasından değil, şimşeğin yolundaki havanın aniden genişlemesinden kaynaklanır."} },
  { id:"nat073", t:"nature", d:4, k:"tf", v:true, en:{q:"Bamboo belongs to the same plant family as grasses."}, tr:{q:"Bambu, çimenlerle aynı bitki familyasına aittir."}, ex:{en:"Bamboo is technically a giant grass, part of the same plant family as lawn grass and wheat.",tr:"Bambu aslında dev bir ottur ve çim ile buğdayla aynı bitki ailesindendir."} },
  { id:"nat074", t:"nature", d:4, k:"tf", v:false, en:{q:"Mushrooms and other fungi belong to the plant kingdom."}, tr:{q:"Mantarlar, bitkiler âlemine ait canlılardır."}, ex:{en:"Fungi form their own separate kingdom; they cannot photosynthesise like plants and instead absorb food.",tr:"Mantarlar kendi ayrı bir alemi oluşturur; bitkiler gibi fotosentez yapamaz, besinlerini emerek alırlar."} },
  { id:"nat075", t:"nature", d:5, c:0, en:{q:"Which mammal lays eggs?",a:["Platypus","Bat","Mole","Squirrel"]}, tr:{q:"Hangi memeli yumurtlar?",a:["Ornitorenk","Yarasa","Köstebek","Sincap"]}, ex:{en:"The platypus is one of only a few mammals that lay eggs instead of giving birth to live young.",tr:"Ornitorenk, canlı yavru doğurmak yerine yumurtlayan az sayıdaki memeliden biridir."} },
  { id:"nat076", t:"nature", d:5, c:0, en:{q:"Which sea creature has three hearts?",a:["Octopus","Jellyfish","Starfish","Sea turtle"]}, tr:{q:"Hangi deniz canlısının üç kalbi vardır?",a:["Ahtapot","Denizanası","Denizyıldızı","Deniz kaplumbağası"]}, ex:{en:"An octopus has three hearts: two pump blood through the gills, and one pumps it round the rest of the body.",tr:"Ahtapotun üç kalbi vardır: ikisi kanı solungaçlardan pompalar, biri de vücudun geri kalanına pompalar."} },
  { id:"nat077", t:"nature", d:5, c:0, en:{q:"What is a group of lions called?",a:["A pride","A pack","A herd","A flock"]}, tr:{q:"Aslan topluluğuna ne ad verilir?",a:["Sürü (pride)","Kürek","Kervan","Küme"]}, ex:{en:"Lions are the only big cats that live in social groups, called prides, usually led by related females.",tr:"Aslanlar, genellikle akraba dişilerin öncülük ettiği, sürü halinde yaşayan tek büyük kedigildir."} },
  { id:"nat078", t:"nature", d:5, c:0, en:{q:"Which instrument measures air pressure in the atmosphere?",a:["Barometer","Thermometer","Anemometer","Hygrometer"]}, tr:{q:"Atmosferdeki hava basıncını ölçen alet hangisidir?",a:["Barometre","Termometre","Anemometre","Higrometre"]}, ex:{en:"A barometer measures air pressure, which often rises before fair weather and falls before storms.",tr:"Barometre hava basıncını ölçer; basınç genellikle güzel havadan önce yükselir, fırtınadan önce düşer."} },
  { id:"nat079", t:"nature", d:5, c:0, en:{q:"In an ecosystem, what are organisms that break down dead plants and animals called?",a:["Decomposers","Producers","Herbivores","Predators"]}, tr:{q:"Bir ekosistemde ölü bitki ve hayvanları parçalayan canlılara ne ad verilir?",a:["Ayrıştırıcılar","Üreticiler","Otoburlar","Yırtıcılar"]}, ex:{en:"Decomposers, like fungi and bacteria, break down dead matter and return its nutrients to the soil.",tr:"Mantar ve bakteri gibi ayrıştırıcılar, ölü canlıları parçalayarak besinlerini toprağa geri döndürür."} },
  { id:"nat080", t:"nature", d:5, c:0, en:{q:"Which bird is known for being able to fly backwards?",a:["Hummingbird","Owl","Stork","Robin"]}, tr:{q:"Hangi kuş geriye doğru uçabilmesiyle bilinir?",a:["Sinek kuşu","Baykuş","Leylek","Kızılgerdan"]}, ex:{en:"A hummingbird's unique wing joint lets it flip its wings, letting it fly backwards and hover in place.",tr:"Sinek kuşunun benzersiz kanat eklemi, kanatlarını çevirerek geriye uçmasını ve havada asılı durmasını sağlar."} },
  { id:"nat081", t:"nature", d:5, c:0, en:{q:"Which biome is a treeless plain where the ground below stays frozen all year?",a:["Tundra","Savanna","Prairie","Wetland"]}, tr:{q:"Alt toprağı yıl boyu donmuş kalan ağaçsız ova biyomu hangisidir?",a:["Tundra","Savan","Preri","Sulak alan"]}, ex:{en:"Tundra soil stays permanently frozen just below the surface, so few trees can put down roots there.",tr:"Tundrada toprak yüzeyin hemen altında sürekli donmuş kalır, bu yüzden çok az ağaç orada kök salabilir."} },
  { id:"nat082", t:"nature", d:5, c:0, en:{q:"What is the hard outer covering that supports an insect's body called?",a:["Exoskeleton","Cartilage","Backbone","Cocoon"]}, tr:{q:"Bir böceğin vücudunu destekleyen sert dış örtüye ne ad verilir?",a:["Dış iskelet","Kıkırdak","Omurga","Koza"]}, ex:{en:"An exoskeleton is a hard shell on the outside of an insect's body that supports and protects it.",tr:"Dış iskelet, bir böceğin vücudunun dışında yer alan ve onu destekleyip koruyan sert bir kabuktur."} },
  { id:"nat083", t:"nature", d:5, c:0, en:{q:"How do most bats find flying insects in complete darkness?",a:["By echolocation using sound","By smell","By heat vision","By taste"]}, tr:{q:"Çoğu yarasa zifiri karanlıkta uçan böcekleri nasıl bulur?",a:["Sesle ekolokasyon yaparak","Koku alarak","Isı görüşüyle","Tat alarak"]}, ex:{en:"Bats emit high-pitched calls and read the returning echoes to pinpoint insects flying in total darkness.",tr:"Yarasalar tiz sesler çıkarır ve karanlıkta uçan böceklerin yerini bulmak için geri dönen yankıları okur."} },
  { id:"nat084", t:"nature", d:5, c:0, en:{q:"Which part of a flower produces pollen?",a:["The anther","The stigma","The petal","The sepal"]}, tr:{q:"Çiçeğin hangi kısmı polen üretir?",a:["Başçık (anter)","Tepecik (stigma)","Taç yaprak","Çanak yaprak"]}, ex:{en:"The anther, at the tip of a flower's stamen, is where pollen grains are produced.",tr:"Bir çiçeğin erkek organının ucundaki başçık, polen tanelerinin üretildiği yerdir."} },
  { id:"nat085", t:"nature", d:5, c:0, en:{q:"Coral reefs are built by which kind of living thing?",a:["Tiny animals","Underwater plants","Fungi","Bacteria"]}, tr:{q:"Mercan resifleri hangi tür canlılar tarafından oluşturulur?",a:["Küçük hayvanlar","Su altı bitkileri","Mantarlar","Bakteriler"]}, ex:{en:"Coral reefs are built up over centuries from the hard skeletons of tiny animals called coral polyps.",tr:"Mercan resifleri, mercan polipi denen küçük hayvanların sert iskeletlerinin yüzyıllar boyunca birikmesiyle oluşur."} },
  { id:"nat086", t:"nature", d:5, k:"tf", v:false, en:{q:"Hippos are more closely related to horses than to whales."}, tr:{q:"Su aygırları, balinalara kıyasla atlara daha yakın akrabadır."}, ex:{en:"Hippos share a closer common ancestor with whales and dolphins than with horses.",tr:"Su aygırının ortak atası, atlardan çok balina ve yunuslarla daha yakındır."} },
  { id:"nat087", t:"nature", d:5, k:"tf", v:true, en:{q:"Bamboo is a type of grass, not a tree."}, tr:{q:"Bambu bir ağaç değil, bir çimen türüdür."}, ex:{en:"Bamboo is classed as a grass, one of the fastest-growing plants in the world, not a tree.",tr:"Bambu bir ağaç değil, dünyanın en hızlı büyüyen bitkilerinden biri olan bir ottur."} },
  { id:"nat088", t:"nature", d:5, k:"tf", v:true, en:{q:"The eye at the centre of a hurricane is the calmest part of the storm."}, tr:{q:"Kasırganın merkezindeki göz, fırtınanın en sakin bölümüdür."}, ex:{en:"The eye of a hurricane is a calm, clear area at its centre, surrounded by the storm's fiercest winds.",tr:"Kasırganın gözü, en şiddetli rüzgârlarla çevrili, merkezindeki sakin ve açık bir bölgedir."} },
  { id:"nat089", t:"nature", d:5, k:"tf", v:false, en:{q:"A jellyfish has a small brain in the middle of its body."}, tr:{q:"Denizanalarının vücudunun ortasında küçük bir beyin bulunur."}, ex:{en:"A jellyfish has no brain at all; it senses its surroundings with a simple nerve net spread through its body.",tr:"Denizanasının hiç beyni yoktur; çevresini vücuduna yayılmış basit bir sinir ağıyla algılar."} },
  { id:"nat090", t:"nature", d:6, c:0, en:{q:"Which tree species is the tallest in the world?",a:["Coast redwood","Douglas fir","Eucalyptus","Sitka spruce"]}, tr:{q:"Dünyanın en uzun ağaç türü hangisidir?",a:["Sahil sekoyası","Douglas göknarı","Okaliptüs","Sitka ladini"]} },
  { id:"nat091", t:"nature", d:6, c:0, en:{q:"Which mammal is thought to have the longest lifespan?",a:["Bowhead whale","African elephant","Blue whale","Human"]}, tr:{q:"En uzun yaşadığı düşünülen memeli hangisidir?",a:["Grönland balinası","Afrika fili","Mavi balina","İnsan"]} },
  { id:"nat092", t:"nature", d:6, c:0, en:{q:"What is the process by which a caterpillar becomes a butterfly called?",a:["Metamorphosis","Mitosis","Migration","Mutation"]}, tr:{q:"Tırtılın kelebeğe dönüşme sürecine ne ad verilir?",a:["Başkalaşım (metamorfoz)","Mitoz","Göç","Mutasyon"]} },
  { id:"nat093", t:"nature", d:6, c:0, en:{q:"Which is the largest fish species in the world?",a:["Whale shark","Great white shark","Tiger shark","Manta ray"]}, tr:{q:"Dünyanın en büyük balık türü hangisidir?",a:["Balina köpekbalığı","Büyük beyaz köpekbalığı","Kaplan köpekbalığı","Manta vatozu"]} },
  { id:"nat094", t:"nature", d:6, c:0, en:{q:"What is the scientific study of insects called?",a:["Entomology","Ornithology","Botany","Ichthyology"]}, tr:{q:"Böcekleri inceleyen bilim dalının adı nedir?",a:["Entomoloji","Ornitoloji","Botanik","İktiyoloji"]} },
  { id:"nat095", t:"nature", d:6, c:0, en:{q:"Which gas makes up the largest share of Earth's atmosphere?",a:["Nitrogen","Oxygen","Carbon dioxide","Argon"]}, tr:{q:"Dünya atmosferinin en büyük bölümünü hangi gaz oluşturur?",a:["Azot","Oksijen","Karbondioksit","Argon"]} },
  { id:"nat096", t:"nature", d:6, c:0, en:{q:"Which group of plants reproduces by spores rather than seeds?",a:["Ferns","Conifers","Grasses","Orchids"]}, tr:{q:"Hangi bitki grubu tohumla değil sporla ürer?",a:["Eğrelti otları","Kozalaklılar","Buğdaygiller (çimenler)","Orkideler"]} },
  { id:"nat097", t:"nature", d:6, c:0, en:{q:"Which animal's antlers are shed and grown again every year?",a:["Deer","Goat","Bison","Rhinoceros"]}, tr:{q:"Hangi hayvanın boynuzları her yıl dökülüp yeniden çıkar?",a:["Geyik","Keçi","Bizon","Gergedan"]} },
  { id:"nat098", t:"nature", d:6, c:0, en:{q:"Which cloud type is associated with thunderstorms?",a:["Cumulonimbus","Cirrus","Stratus","Altocumulus"]}, tr:{q:"Gök gürültülü fırtınalarla ilişkilendirilen bulut türü hangisidir?",a:["Kümülonimbüs","Sirüs","Stratüs","Altokümülüs"]} },
  { id:"nat099", t:"nature", d:6, c:0, en:{q:"What is the main cause of ocean tides on Earth?",a:["The Moon's gravitational pull","Ocean currents","Prevailing winds","Earth's magnetic field"]}, tr:{q:"Dünya'daki gelgitlerin başlıca nedeni nedir?",a:["Ay'ın çekim kuvveti","Okyanus akıntıları","Hâkim rüzgârlar","Dünya'nın manyetik alanı"]} },
  { id:"nat100", t:"nature", d:6, c:0, en:{q:"Which of these animals is a marsupial?",a:["Koala","Sloth","Lemur","Meerkat"]}, tr:{q:"Bu hayvanlardan hangisi keseli bir hayvandır?",a:["Koala","Tembel hayvan","Lemur","Mirket"]} },
  { id:"nat101", t:"nature", d:6, c:0, en:{q:"What word describes a species found naturally in only one region?",a:["Endemic","Invasive","Migratory","Extinct"]}, tr:{q:"Doğal olarak yalnızca tek bir bölgede bulunan tür için hangi sözcük kullanılır?",a:["Endemik","İstilacı","Göçmen","Soyu tükenmiş"]} },
  { id:"nat102", t:"nature", d:6, c:0, en:{q:"Which treeless biome lies north of the boreal forests?",a:["Tundra","Savanna","Steppe","Rainforest"]}, tr:{q:"Boreal ormanların (tayga) kuzeyinde uzanan ağaçsız biyom hangisidir?",a:["Tundra","Savan","Bozkır (step)","Yağmur ormanı"]} },
  { id:"nat103", t:"nature", d:6, k:"tf", v:true, en:{q:"An octopus has blue blood."}, tr:{q:"Ahtapotun kanı mavidir."} },
  { id:"nat104", t:"nature", d:6, k:"tf", v:true, en:{q:"Honeybees use a waggle dance to tell the hive the direction and distance of food."}, tr:{q:"Bal arıları, besinin yönünü ve uzaklığını kovandaki diğer arılara sallanma dansıyla bildirir."} },
  { id:"nat105", t:"nature", d:6, k:"tf", v:false, en:{q:"A rhinoceros horn is made of solid bone."}, tr:{q:"Gergedanın boynuzu som kemikten oluşur."} },
  { id:"nat106", t:"nature", d:6, k:"tf", v:true, en:{q:"In seahorses, the male carries the eggs in a pouch and gives birth to the young."}, tr:{q:"Deniz atlarında erkek, yumurtaları kesesinde taşır ve yavruları dünyaya getirir."} },
  { id:"nat107", t:"nature", d:6, k:"tf", v:false, en:{q:"The eye at the centre of a hurricane is where the strongest winds blow."}, tr:{q:"Kasırganın merkezindeki göz, en şiddetli rüzgârların estiği bölümdür."} },
  { id:"nat108", t:"nature", d:6, k:"tf", v:true, en:{q:"Antarctica is classified as a desert because it receives very little precipitation."}, tr:{q:"Antarktika, çok az yağış aldığı için çöl olarak sınıflandırılır."} },
  { id:"nat109", t:"nature", d:7, c:0, en:{q:"Which bird makes the longest annual migration?",a:["Arctic tern","Albatross","Swift","Barn swallow"]}, tr:{q:"Hangi kuş yılda en uzun göçü yapar?",a:["Kuzey sumrusu","Albatros","Ebabil","Kır kırlangıcı"]} },
  { id:"nat110", t:"nature", d:7, c:0, en:{q:"What is the name for an animal that is active mainly at dawn and dusk?",a:["Crepuscular","Nocturnal","Diurnal","Sedentary"]}, tr:{q:"Ağırlıklı olarak şafak ve alacakaranlıkta faal olan hayvanlara ne denir?",a:["Krepüsküler","Noktürnal","Diürnal","Sedanter"]} },
  { id:"nat111", t:"nature", d:7, c:0, en:{q:"What is the name for the warm, dry wind that descends the lee side of a mountain range?",a:["Foehn","Mistral","Sirocco","Monsoon"]}, tr:{q:"Bir sıradağın rüzgâraltı yamacından aşağı inen sıcak ve kuru rüzgâra ne ad verilir?",a:["Fön","Mistral","Siroko","Muson"]} },
  { id:"nat112", t:"nature", d:7, c:0, en:{q:"In ecology, what does the term \"ecotone\" describe?",a:["A transition zone between two habitats","A species' role in its ecosystem","A lifeless, oxygen-poor zone in a lake","The upper layer of a forest canopy"]}, tr:{q:"Ekolojide \"ekoton\" terimi neyi ifade eder?",a:["İki habitat arasındaki geçiş bölgesi","Bir türün ekosistemdeki rolü","Gölde oksijensiz, cansız bölge","Orman örtüsünün en üst tabakası"]} },
  { id:"nat113", t:"nature", d:7, c:0, en:{q:"In a cow, which stomach compartment is the \"true stomach\" that secretes digestive acid?",a:["Abomasum","Rumen","Reticulum","Omasum"]}, tr:{q:"İneklerde sindirim asidi salgılayan \"asıl mide\" bölmesi hangisidir?",a:["Şirden","İşkembe","Börkenek","Kırkbayır"]} },
  { id:"nat114", t:"nature", d:7, c:0, en:{q:"A Venus flytrap's trap snaps shut only after its trigger hairs are touched how many times?",a:["Twice","Once","Five times","Ten times"]}, tr:{q:"Venüs sinekkapanının tuzağı, duyarga tüylerine kaç kez dokunulduktan sonra kapanır?",a:["İki kez","Bir kez","Beş kez","On kez"]} },
  { id:"nat115", t:"nature", d:7, c:0, en:{q:"Which ocean layer, from about 200 to 1,000 metres deep, is known as the twilight zone?",a:["Mesopelagic","Epipelagic","Bathypelagic","Abyssopelagic"]}, tr:{q:"Yaklaşık 200-1.000 m derinlikteki, alacakaranlık bölgesi denen okyanus katmanı hangisidir?",a:["Mezopelajik","Epipelajik","Batipelajik","Abisopelajik"]} },
  { id:"nat116", t:"nature", d:7, c:0, en:{q:"North America's periodical cicadas emerge from the ground in cycles of how many years?",a:["13 or 17","3 or 5","7 or 9","20 or 25"]}, tr:{q:"Kuzey Amerika'nın periyodik ağustosböcekleri kaç yıllık döngülerle topraktan çıkar?",a:["13 veya 17","3 veya 5","7 veya 9","20 veya 25"]} },
  { id:"nat117", t:"nature", d:7, c:0, en:{q:"Males of which bird family build decorated structures on the ground to attract mates?",a:["Bowerbirds","Weaverbirds","Lyrebirds","Hornbills"]}, tr:{q:"Hangi kuş ailesinin erkekleri, dişileri etkilemek için yere süslü yapılar inşa eder?",a:["Çardak kuşları","Dokumacı kuşlar","Lir kuşları","Boynuzgagalar"]} },
  { id:"nat118", t:"nature", d:7, c:0, en:{q:"Which is the only fish species able to live in Turkey's highly alkaline Lake Van?",a:["Pearl mullet","Common carp","Brown trout","European eel"]}, tr:{q:"Türkiye'nin sodalı Van Gölü'nde yaşayabilen tek balık türü hangisidir?",a:["İnci kefali","Sazan","Alabalık","Yılan balığı"]} },
  { id:"nat119", t:"nature", d:7, c:0, en:{q:"Which pigments make autumn leaves yellow once the chlorophyll has broken down?",a:["Carotenoids","Anthocyanins","Melanins","Phycobilins"]}, tr:{q:"Klorofil parçalandıktan sonra sonbahar yapraklarına sarı rengini hangi pigmentler verir?",a:["Karotenoidler","Antosiyaninler","Melaninler","Fikobilinler"]} },
  { id:"nat120", t:"nature", d:7, c:0, en:{q:"The axolotl keeps its gills and larval body for life. What is retaining juvenile traits called?",a:["Neoteny","Diapause","Aestivation","Mimicry"]}, tr:{q:"Aksolotl, solungaçlarını ve larva biçimini ömür boyu korur. Bu duruma ne ad verilir?",a:["Neoteni","Diyapoz","Estivasyon","Mimikri"]} },
  { id:"nat121", t:"nature", d:7, k:"tf", v:true, en:{q:"Naked mole-rats live in colonies where only one female, the queen, produces young."}, tr:{q:"Çıplak köstebek fareleri, yalnızca tek bir dişinin (kraliçenin) ürediği koloniler hâlinde yaşar."} },
  { id:"nat122", t:"nature", d:7, k:"tf", v:true, en:{q:"Pando, an aspen grove in Utah, is one organism whose thousands of trunks share a single root system."}, tr:{q:"Utah'taki Pando titrek kavak korusu tek bir organizmadır; binlerce gövdesi tek bir kök sistemini paylaşır."} },
  { id:"nat123", t:"nature", d:7, k:"tf", v:false, en:{q:"A lightning bolt heats the air in its channel to about 3,000 °C."}, tr:{q:"Yıldırım, içinden geçtiği hava kanalını yaklaşık 3.000 °C'ye kadar ısıtır."} },
  { id:"nat124", t:"nature", d:7, k:"tf", v:false, en:{q:"In ecology, a keystone species means the species that is most numerous in its habitat."}, tr:{q:"Ekolojide anahtar tür, yaşam alanında sayıca en çok bulunan tür demektir."} },
  { id:"nat125", t:"nature", d:7, k:"tf", v:true, en:{q:"Poison dart frogs get their toxins from their wild diet, so captive-bred ones are not poisonous."}, tr:{q:"Zehirli ok kurbağaları zehrini doğadaki besinlerinden alır; esaret altında yetiştirilenler zehirsizdir."} },
  { id:"nat126", t:"nature", d:8, c:0, en:{q:"Which symbiotic pairing forms a lichen?",a:["A fungus and an alga","Two fungi","A moss and a fern","A bacterium and a moss"]}, tr:{q:"Bir liken hangi ortak yaşam ikilisinden oluşur?",a:["Bir mantar ve bir alg","İki mantar","Bir yosun ve bir eğrelti","Bir bakteri ve bir yosun"]} },
  { id:"nat127", t:"nature", d:8, c:0, en:{q:"Which animal group does the phylum Echinodermata contain?",a:["Starfish and sea urchins","Crabs and lobsters","Snails and clams","Corals and jellyfish"]}, tr:{q:"Derisidikenliler (Echinodermata) şubesi hangi hayvanları kapsar?",a:["Denizyıldızı ve deniz kestanesi","Yengeç ve ıstakoz","Salyangoz ve midye","Mercan ve denizanası"]} },
  { id:"nat128", t:"nature", d:8, c:0, en:{q:"Which rule states that animals in colder climates tend to have larger bodies?",a:["Bergmann's rule","Allen's rule","Gloger's rule","Cope's rule"]}, tr:{q:"Soğuk iklimlerdeki hayvanların daha iri gövdeli olma eğilimini hangi kural anlatır?",a:["Bergmann kuralı","Allen kuralı","Gloger kuralı","Cope kuralı"]} },
  { id:"nat129", t:"nature", d:8, c:0, en:{q:"Which metal sits at the heart of hemocyanin, the blue blood pigment of crabs and snails?",a:["Copper","Iron","Zinc","Magnesium"]}, tr:{q:"Yengeç ve salyangozların mavi kan pigmenti hemosiyaninin merkezinde hangi metal bulunur?",a:["Bakır","Demir","Çinko","Magnezyum"]} },
  { id:"nat130", t:"nature", d:8, c:0, en:{q:"In flowering plants, double fertilisation creates the embryo and which nutritive tissue?",a:["Endosperm","Cotyledon","Pericarp","Seed coat"]}, tr:{q:"Çiçekli bitkilerde çift döllenme, embriyonun yanı sıra hangi besleyici dokuyu oluşturur?",a:["Endosperm (besidoku)","Çenek (kotiledon)","Perikarp (meyve duvarı)","Tohum kabuğu"]} },
  { id:"nat131", t:"nature", d:8, c:0, en:{q:"The Wallace Line, dividing Asian and Australian fauna, runs between which two islands?",a:["Bali and Lombok","Java and Sumatra","Luzon and Mindanao","Honshu and Kyushu"]}, tr:{q:"Asya ve Avustralya faunasını ayıran Wallace Hattı hangi iki ada arasından geçer?",a:["Bali ve Lombok","Java ve Sumatra","Luzon ve Mindanao","Honshu ve Kyushu"]} },
  { id:"nat132", t:"nature", d:8, c:0, en:{q:"Which ocean layer, roughly 1,000 to 4,000 m deep, is known as the midnight zone?",a:["Bathypelagic","Mesopelagic","Epipelagic","Abyssopelagic"]}, tr:{q:"Yaklaşık 1.000–4.000 m derinlikteki, \"gece yarısı bölgesi\" denen okyanus katmanı hangisidir?",a:["Batipelajik","Mezopelajik","Epipelajik","Abisopelajik"]} },
  { id:"nat133", t:"nature", d:8, c:0, en:{q:"Which organ do birds use to produce their song?",a:["The syrinx","The larynx","The crop","The gizzard"]}, tr:{q:"Kuşlar ötüşlerini hangi organla üretir?",a:["Sirinks","Gırtlak (larinks)","Kursak","Taşlık"]} },
  { id:"nat134", t:"nature", d:8, c:0, en:{q:"Which is the only primate known to be venomous?",a:["The slow loris","The aye-aye","The tarsier","The marmoset"]}, tr:{q:"Zehirli (venomlu) olduğu bilinen tek primat hangisidir?",a:["Yavaş loris","Aye-aye","Tarsier (cadı maki)","Marmoset"]} },
  { id:"nat135", t:"nature", d:8, c:0, en:{q:"Which conifer was known only from fossils until living trees were found in China in the 1940s?",a:["Dawn redwood (Metasequoia)","Monkey puzzle","Norfolk Island pine","Cedar of Lebanon"]}, tr:{q:"Hangi kozalaklı ağaç, 1940'larda Çin'de canlı örnekleri bulunana dek yalnızca fosillerden biliniyordu?",a:["Metasequoia (şafak sekoyası)","Şili çamı (araukarya)","Norfolk çamı","Lübnan sediri"]} },
  { id:"nat136", t:"nature", d:8, c:0, en:{q:"What is the meteorological term for precipitation that evaporates before reaching the ground?",a:["Virga","Graupel","Rime","Squall line"]}, tr:{q:"Yere ulaşmadan buharlaşan yağış için kullanılan meteorolojik terim nedir?",a:["Virga","Graupel (yumuşak dolu)","Kırç","Fırtına hattı"]} },
  { id:"nat137", t:"nature", d:8, c:0, en:{q:"In Müllerian mimicry, what is true of the species that come to resemble one another?",a:["All are genuinely harmful","All are completely harmless","Harmless species copy a harmful one","Predators copy their prey"]}, tr:{q:"Müller taklitçiliğinde birbirine benzeyen türler için doğru olan nedir?",a:["Hepsi gerçekten zararlıdır","Hepsi tamamen zararsızdır","Zararsız tür zararlıyı taklit eder","Avcı, avını taklit eder"]} },
  { id:"nat138", t:"nature", d:8, k:"tf", v:true, en:{q:"In the stratosphere, air temperature rises as you climb higher, instead of falling."}, tr:{q:"Stratosferde yükseldikçe hava sıcaklığı düşmez, artar."} },
  { id:"nat139", t:"nature", d:8, k:"tf", v:false, en:{q:"In sea turtles, eggs that incubate in warmer sand hatch out mostly as males."}, tr:{q:"Deniz kaplumbağalarında daha sıcak kumda gelişen yumurtalardan çoğunlukla erkek yavrular çıkar."} },
  { id:"nat140", t:"nature", d:8, k:"tf", v:true, en:{q:"Dust carried across the Atlantic from the Sahara fertilises the Amazon rainforest with phosphorus."}, tr:{q:"Sahra Çölü'nden Atlantik'i aşarak gelen toz, Amazon yağmur ormanını fosforla gübreler."} },
  { id:"nat141", t:"nature", d:8, k:"tf", v:false, en:{q:"The baleen plates whales use to strain food from seawater are made of bone."}, tr:{q:"Balinaların deniz suyundan besin süzmek için kullandığı balen levhaları kemikten yapılmıştır."} },
  { id:"nat142", t:"nature", d:8, k:"tf", v:true, en:{q:"Cacti open their stomata at night rather than by day, taking in carbon dioxide after dark."}, tr:{q:"Kaktüsler gözeneklerini (stoma) gündüz değil gece açar ve karbondioksiti karanlıkta alır."} }
);
